from __future__ import annotations

import base64
import io
import zipfile
from pathlib import Path

PAYLOAD = '[...truncated...]UEsBAhQDFAAAAAgAFEoGXampl57VDQAAf0gAADUAAAAAAAAAAAAAACAAZE0AAB0ZXN0cy90ZXN0X2xvdDI5X3YyX2RldGVybWluaXN0aWNfcmVwbGF5X2FuZF9hdWRpdC5weVBLBQYAAAAACgAKAMUDAAC5QgAAAAA='
ROOT = Path(__file__).resolve().parents[1]


def main() -> int:
    archive = zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD)))
    for member in archive.infolist():
        target = (ROOT / member.filename).resolve()
        if ROOT.resolve() not in target.parents:
            raise RuntimeError(f"unsafe archive path: {member.filename}")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(archive.read(member))
    Path(__file__).unlink()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
